python3 -c "
import json

path = '/root/gen-depth-fingerprint/data/qwen3-1.7b/generations_shard0.jsonl'
seeds = {}
lines = 0
errors = 0

with open(path) as f:
    for i, line in enumerate(f, 1):
        try:
            d = json.loads(line)
            sid = d.get('seed_id', d.get('seed'))
            dep = d.get('depth', 0)
            if sid not in seeds:
                seeds[sid] = set()
            if dep in seeds[sid]:
                print(f'DUPLICATE: line {i}, seed={sid}, depth={dep}')
            seeds[sid].add(dep)
            lines += 1
        except Exception as e:
            errors += 1
            print(f'JSON ERROR line {i}: {e}')

gaps = 0
for sid, depths in seeds.items():
    max_d = max(depths)
    for d in range(max_d + 1):
        if d not in depths:
            gaps += 1
            if gaps <= 10:
                print(f'GAP: seed={sid} missing depth={d} (has {sorted(depths)})')

print(f'\nSummary: {lines} lines, {len(seeds)} seeds, {errors} JSON errors, {gaps} depth gaps')
print(f'Seeds with all 5 depths: {sum(1 for s in seeds.values() if len(s)==5)}')
print(f'Seeds with <5 depths: {sum(1 for s in seeds.values() if len(s)<5)}')

from collections import Counter
depth_counts = Counter()
for s, ds in seeds.items():
    for d in ds:
        depth_counts[d] += 1
print(f'Depth dist: {dict(sorted(depth_counts.items()))}')
"

